from itertools import product
def tryfit(name,f,p0):
    best=None
    for s in range(20):
        p=np.random.RandomState(s).randn(len(p0))*np.array(p0)
        try:
            r=so.least_squares(lambda q: f(q)-sigma, p, max_nfev=5000)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    print(name, np.round(best.x,4), 'NMSE', np.mean(best.fun**2)/np.var(sigma))
